/**
 * The public claim type.
 *
 * The site already had a machine-level evidence layer: an id resolves to a
 * record, and a build check walks the rendered HTML for numbers that do not.
 * What it did not have was a public one. A visitor was shown
 * `campaign.adjudication.ADJ-AVP` and expected to decode it, and a sentence
 * asserting "the software can do X", a sentence reporting a fixture test, and
 * a sentence reporting one measured run all rendered with identical authority.
 *
 * This is the layer over the store, not a replacement for it. Every field here
 * is generated by scripts/build_claims.mjs from data that already exists; no
 * claim is hand-written, and no public number is typed into a component.
 *
 * THE TYPE IS WHAT DECIDES HOW A STATEMENT RENDERS. That is the whole point of
 * separating it from the evidence record, which knows only that a number came
 * from somewhere.
 */

export type PublicClaimType =
  /** Needs a source or a canonical project contract. */
  | "definition"
  /** Needs a released API and a working example. */
  | "software-capability"
  /** Needs the exact fixture and the acceptance check. */
  | "fixture-qualification"
  /** Needs subject, quantity, unit, comparator, scope, source, limitation. */
  | "measured-result"
  /** All of the above plus the transform. */
  | "derived-result"
  /** Must NOT inherit the visual certainty of a measured result. */
  | "interpretation"
  /** Future or conditional language only. */
  | "open-hypothesis"
  /** A stated limit on what the project claims. */
  | "limitation";

/**
 * The four outcome words, which are never interchanged.
 *
 * The store's own word for a held prediction is `confirmed`; this layer's is
 * `supported`. That rename is the ONLY mapping applied, it is recorded in
 * `OUTCOME_TO_STATUS`, and scripts/checks/claims-public.mjs asserts every
 * claim's status against its source outcome under it. `mixed`, which
 * cards.json carries on 7 of 27 cards, has no member here and is deliberately
 * left without one rather than being folded into the nearest word.
 */
export type PublicClaimStatus = "supported" | "refuted" | "inconclusive" | "unrun";

export interface PublicClaimQuantity {
  /** The measured quantity's own name, as the source records it. */
  name: string;
  value: number | string;
  /** null where the source states no unit. Never guessed, never "" for none. */
  unit: string | null;
  /** What a positive or negative value means, where the sign is load-bearing. */
  signMeaning?: string;
  /** "share of total comparison energy", "AUROC difference". */
  scale?: string;
  /** "± 0.004", "95% CI [-0.005, -0.002]". Composed by the adapter, never here. */
  uncertainty?: string;
}

export interface PublicClaim {
  /** Components import by this, never by array index. */
  slug: string;
  label: string;
  statement: string;
  type: PublicClaimType;
  status?: PublicClaimStatus;
  subject?: string;
  quantity?: PublicClaimQuantity;
  comparator?: string;
  /** Required. What the claim ranges over, and therefore what it does not. */
  scope: string;
  /** Required. What this claim does not establish. */
  limitation: string;
  /** Required. Prose. A machine identifier here is a generator failure. */
  humanSource: string;
  sourceUrl?: string;
  artifact?: string;
  /** Machine ids. NEVER shown in a normal disclosure. */
  immutableIds: string[];
  contentHash: string;
}

/** The one rename this layer applies, and the only one it is allowed to. */
export const OUTCOME_TO_STATUS: Readonly<Record<string, PublicClaimStatus>> = {
  confirmed: "supported",
  refuted: "refuted",
  inconclusive: "inconclusive",
  unrun: "unrun",
};
